        val tree=IntArray(4*size+4);
        fun query(node:Int,left:Int,right:Int,ql:Int,qr:Int):Int{
            if(ql>right||qr<left)return 0;
            if(ql<=left&&right<=qr)return tree[node];
            val middle=(left+right)/2;
            return maxOf(query(node*2,left,middle,ql,qr),query(node*2+1,middle+1,right,ql,qr))
        };
        fun update(node:Int,left:Int,right:Int,index:Int,value:Int){
            if(left==right){
                tree[node]=maxOf(tree[node],value);
                return
            };
            val middle=(left+right)/2;
            if(index<=middle)update(node*2,left,middle,index,value)else update(node*2+1,middle+1,right,index,value);
            tree[node]=maxOf(tree[node*2],tree[node*2+1])
        };
